// Module : i18n

const UI_LANGUAGE_STORAGE = "compagnon-language";
let selectedUiLanguagePreference = "auto";
try {
  const saved = localStorage.getItem(UI_LANGUAGE_STORAGE);
  if (saved === "fr" || saved === "en") selectedUiLanguagePreference = saved;
} catch { /* La préférence reste disponible en mémoire. */ }
function deviceUiLanguage() {
  const browser = typeof window === "undefined" ? null : window.navigator;
  const languages = browser?.languages?.length ? browser.languages : [browser?.language || "fr"];
  return languages.map(language => language.toLowerCase().split("-")[0]).find(language => language === "fr" || language === "en") || "fr";
}
function uiLanguagePreference() { return selectedUiLanguagePreference; }
function uiLanguage() { return selectedUiLanguagePreference === "auto" ? deviceUiLanguage() : selectedUiLanguagePreference; }
function uiLocale() { return uiLanguage() === "en" ? "en-US" : "fr-FR"; }

/** Ne lit ni ne modifie les personnages, leurs brouillons ou leurs textes. */
function setUiLanguage(language) {
  selectedUiLanguagePreference = ["fr", "en"].includes(language) ? language : "auto";
  try {
    localStorage.setItem(UI_LANGUAGE_STORAGE, selectedUiLanguagePreference);
    return true;
  } catch { return false; }
}

// Une erreur ou un aperçu déjà calculé peut survivre à la bascule. Les paramètres
// restent opaques et locaux ; cette mémoire bornée ne contient aucune fiche.
const uiPresentedParameters = new Map();
const uiMessageKeys = new Map();
for (const [key, text] of Object.entries(UI_FR)) uiMessageKeys.set(text, key);
for (const [key, text] of Object.entries(UI_EN)) uiMessageKeys.set(text, key);

/** Les paramètres sont des valeurs opaques : aucune traduction de saisie personnelle. */
function uiText(key, parameters = {}) {
  const dictionary = uiLanguage() === "en" ? UI_EN : UI_FR;
  const text = dictionary[key] ?? UI_EN[key] ?? UI_FR[key];
  if (text === undefined) throw new Error(`Unknown interface text: ${key}`);
  const rendered = text.replace(/\{([\w]+)\}/g, (match, name) => Object.hasOwn(parameters, name) ? String(parameters[name]) : match);
  if (Object.keys(parameters).length) {
    uiPresentedParameters.set(rendered, { key, parameters: { ...parameters } });
    if (uiPresentedParameters.size > 512) uiPresentedParameters.delete(uiPresentedParameters.keys().next().value);
  }
  return rendered;
}

/** Retraduit uniquement un message système déjà identifié, jamais un champ personnel. */
function uiPresentedText(text) {
  const record = uiPresentedParameters.get(text);
  if (record) return uiText(record.key, record.parameters);
  const key = uiMessageKeys.get(text);
  return key === undefined ? text : uiText(key);
}


// Module : units
// Conventions de jeu 2014 déjà employées par le catalogue et le moteur.
// Ces coefficients ne sont pas des conversions physiques SI.
const UNIT_STORAGE_KEY = "compagnon-units";
const GAME_UNITS = { m: { kind: "distance", metric: 1 }, ft: { kind: "distance", metric: 0.3 }, km: { kind: "travel", metric: 1 }, mi: { kind: "travel", metric: 1.6 }, kg: { kind: "mass", metric: 1 }, lb: { kind: "mass", metric: 0.5 } };
let selectedUnitSystem = "metric";
try { selectedUnitSystem = localStorage.getItem(UNIT_STORAGE_KEY) === "imperial" ? "imperial" : "metric"; } catch { /* Préférence en mémoire si le stockage est indisponible. */ }

function unitSystem() { return selectedUnitSystem; }

/** Préférence de présentation, indépendante des personnages et de la langue. */
function setUnitSystem(system) {
  selectedUnitSystem = system === "imperial" ? "imperial" : "metric";
  try { localStorage.setItem(UNIT_STORAGE_KEY, selectedUnitSystem); return true; } catch { return false; }
}

function convertGameUnit(value, from, to) {
  if (!Number.isFinite(value) || !GAME_UNITS[from] || GAME_UNITS[from].kind !== GAME_UNITS[to]?.kind) throw new Error("Incompatible game units");
  return from === to ? value : value * GAME_UNITS[from].metric / GAME_UNITS[to].metric;
}

function formatUnitNumber(value, language = "fr", maximumFractionDigits = 2) {
  return new Intl.NumberFormat(language === "en" ? "en-US" : "fr-FR", { maximumFractionDigits }).format(value);
}

function gameUnitTarget(from, system = unitSystem()) {
  const kind = GAME_UNITS[from]?.kind;
  if (!kind) throw new Error("Unknown game unit");
  return (system === "imperial" ? { distance: "ft", travel: "mi", mass: "lb" } : { distance: "m", travel: "km", mass: "kg" })[kind];
}

/** Une seule conversion depuis la valeur technique, jamais depuis le texte arrondi. */
function formatGameMeasure(value, from, { system = unitSystem(), language = "fr", source = false, maximumFractionDigits = 6 } = {}) {
  const to = gameUnitTarget(from, system);
  const displayed = `${formatUnitNumber(convertGameUnit(value, from, to), language, maximumFractionDigits)} ${to}`;
  return source && to !== from ? `${displayed} (${formatUnitNumber(value, language, 12)} ${from})` : displayed;
}

/** Le tri garde l'identité technique ; les accents et nombres sont comparables. */
function compareUnitLabels(a, b, language = "fr") {
  return new Intl.Collator(language === "en" ? "en" : "fr", { sensitivity: "base", numeric: true }).compare(a, b);
}


// Module : catalog
