const WEAPON_GROUPS = {
  simple: { name: "Armes courantes", matches: (weapon) => weapon.group === "simple" },
  martial: { name: "Armes de guerre", matches: (weapon) => weapon.group === "martial" },
  firearms: { name: "Armes à feu", matches: (weapon) => weapon.firearm === true },
};
function weaponInGroup(weapon, groupId) {
  return !!weapon && typeof groupId === "string" && Object.hasOwn(WEAPON_GROUPS, groupId) && WEAPON_GROUPS[groupId].matches(weapon);
}
function weaponProficiencyLabel(id) {
  return Object.hasOwn(WEAPON_GROUPS, id) ? WEAPON_GROUPS[id].name : Object.hasOwn(WEAPONS, id) ? WEAPONS[id].name : id;
}

