// Les profils acquis gardent leurs choix et leurs identifiants ; les versions restent regroupées.
for (const profile of Object.values(BACKGROUND_REFERENCE_DATA).filter((entry) => !entry.variantId && entry.id !== "custom")) {
  const existing = BACKGROUNDS[profile.id];
  if (existing) Object.assign(existing, { referenceId: profile.referenceId, revision: profile.revision, aliases: [...new Set([...(existing.aliases || []), ...profile.aliases])] });
  else BACKGROUNDS[profile.id] = { ...profile, variants: [] };
  const equipment = BACKGROUND_EQUIPMENT_RULES[profile.id];
  if (!equipment) BACKGROUND_EQUIPMENT_RULES[profile.id] = profile.equipmentRule;
  else equipment.groups.forEach((group, index) => Object.entries(group).forEach(([key, entries]) => entries.forEach((entry, slot) => {
    const displayName = profile.equipmentRule.groups[index]?.[key]?.[slot]?.displayName;
    if (displayName) entries[slot] = { ...(typeof entry === "string" ? { item: entry } : entry), displayName };
  })));
}
for (const profile of Object.values(BACKGROUND_REFERENCE_DATA).filter((entry) => entry.variantId)) {
  const parent = BACKGROUNDS[profile.id], existing = parent.variants.find((entry) => entry.id === profile.variantId);
  if (existing) existing.referenceId = profile.referenceId;
  else parent.variants.push({ ...profile, id: profile.variantId, profile });
  BACKGROUND_VARIANT_RULES[profile.variantId] = { ...BACKGROUND_VARIANT_RULES[profile.variantId], parent: profile.id, referenceId: profile.referenceId, revision: profile.revision };
  parent.aliases = [...new Set([...(parent.aliases || []), profile.name, ...profile.aliases])];
}

/** Résolution commune à la fiche et au journal d’acquisition, sans modifier les choix stockés. */
function resolveBackgroundProfile(c) {
  const b = c.background || {}, base = BACKGROUNDS[b.id];
  if (!base) return null;
  const selected = (field) => Array.isArray(c.picks?.[`bg|${field}`]) ? c.picks[`bg|${field}`] : [];
  const variant = base.variants.find((entry) => entry.id === b.variantId), rule = BACKGROUND_VARIANT_RULES[b.variantId];
  const result = variant && rule?.parent === b.id
    ? { id: b.id, ...base, ...(variant.profile || {}), id: b.id, name: variant.name, variantId: variant.id, baseName: base.name, referenceId: rule.referenceId, revision: rule.revision || base.revision, feature: variant.feature || (rule.featureName ? [rule.featureName, base.feature[1]] : base.feature), variantRule: rule }
    : { id: b.id, ...base };
  result.grants = { ...result.grants };
  if (variant?.id === "guildMerchant") {
    const training = selected("merchantTraining")[0] || "artisan";
    delete result.grants.toolChoice;
    if (training === "artisan") result.grants.toolChoice = { count: 1, from: "artisan" };
    if (training === "navigators-tools") result.grants.tools = [...(result.grants.tools || []), "navigators-tools"];
    if (training === "language") result.grants.languageChoice = { count: 2 };
  }
  const house = result.houseOptions?.[selected("house")[0]];
  if (house) { result.grants = { ...result.grants, ...house.grants }; result.extraChoices = house.extraChoices; }
  for (const choice of result.extraChoices || []) {
    const values = [...new Set(selected(choice.key))].filter((id) => choice.from.includes(id)).slice(0, choice.count), field = choice.type === "tool" ? "tools" : "languages";
    result.grants[field] = [...(result.grants[field] || []), ...values];
  }
  if (result.featOptions?.length) result.grants.feats = selected("featChoice").filter((id) => result.featOptions.includes(id)).slice(0, 1);
  if (result.id === "clanCrafter") result.grants.languages = ["dwarvish", ...selected("clanLanguage").filter((id) => id !== "dwarvish").slice(0, 1)];
  const secondary = result.id === "dimirOperative" && BACKGROUNDS[selected("secondaryGuild")[0]];
  if (secondary?.source === "ggr" && secondary.id !== "dimirOperative") result.gold = secondary.gold;
  return result;
}


