for (const id of ["fadeAway", "orcishFury", "secondChance"]) _featAddGrants(id, { resources: [{ id: `feat-${id}`, name: FEATS[id].name, max: 1, reset: "short", ...(id === "secondChance" && { note: "Récupère aussi cette utilisation quand tu lances l’initiative : remets alors le compteur à zéro." }) }] });
_featAddGrants("metamagicAdept", { resources: [{ id: "feat-metamagic", name: "Points de sorcellerie du don", max: 2, reset: "long", note: "Deux points supplémentaires réservés à la métamagie. Ils ne peuvent pas créer d’emplacements." }] });
