// Module : artificer

function artificerReference(name, subclass = null) {
  return Object.values(ARTIFICER_REFERENCE_DATA).find((entry) => entry.englishName === name && (subclass ? entry.subclass === subclass : !entry.subclass));
}
function artificerQuotas(level) {
  return { known: level < 2 ? 0 : level < 6 ? 4 : level < 10 ? 6 : level < 14 ? 8 : level < 18 ? 10 : 12,
    infused: level < 2 ? 0 : level < 6 ? 2 : level < 10 ? 3 : level < 14 ? 4 : level < 18 ? 5 : 6,
    attuned: level < 10 ? 3 : level < 14 ? 4 : level < 18 ? 5 : 6 };
}
const ARTIFICER_RECIPES = Object.fromEntries(Object.entries(ARTIFICER_REFERENCE_DATA).filter(([id, ref]) => id.startsWith("optionalfeature|") && ref.englishName !== "Replicate Magic Item").map(([id, ref]) => [id, { ...ref, minLevel: Math.max(2, ...(ref.prerequisite || []).map((p) => p.level?.level || 0)) }]));
const artificerReplication = artificerReference("Replicate Magic Item");
for (const [index, table] of (artificerReplication.englishEntries || []).filter((entry) => entry.type === "table").entries()) {
  const frTable = artificerReplication.entries.filter((entry) => entry.type === "table")[index], minLevel = Number(table.caption.match(/\((\d+)/)?.[1] || 2);
  table.rows.forEach((row, i) => {
    const match = row[0].match(/\{@item ([^}|]+)(?:\|([^}|]+))?/), id = `item|${(match[2] || "DMG").toLowerCase()}|${match[1].toLowerCase()}`;
    ARTIFICER_RECIPES[`replicate:${id}`] = { name: `Réplique : ${frTable.rows[i][0].replace(/\{@\w+ ([^}]+)}/g, (_, body) => { const parts = body.split("|"); return parts[2] || parts[0]; })}`, minLevel, englishName: `Replicate: ${match[1]}`, attunementRequired: row[1] === "Yes", description: `Niveau d’artificier ${minLevel}. Harmonisation : ${frTable.rows[i][1]}.`, referenceId: id, infusionReferenceId: artificerReplication.referenceId };
  });
}
function completeArtificerSubclasses(registry) {
  for (const [id, name] of Object.entries({ alchemist: "Alchemist", armorer: "Armorer", artillerist: "Artillerist", battleSmith: "Battle Smith" })) {
    const ref = Object.values(ARTIFICER_REFERENCE_DATA).find((entry) => entry.referenceId.startsWith("subclass|") && entry.englishName === name);
    registry[id] = { name: ref.name, source: ref.source, referenceId: ref.referenceId, revision: ref.revision, desc: ref.description, features: Object.values(ARTIFICER_REFERENCE_DATA).filter((entry) => entry.referenceId.startsWith("subclassfeature|") && entry.subclass === name).map((entry) => [entry.level, entry.name, entry.description, entry.referenceId]), grants: {}, choices: [], resources: [] };
  }
  registry.battleSmith.alwaysPrepared = [[3, "heroism", "shield"], [5, "branding-smite", "warding-bond"], [9, "aura-of-vitality", "conjure-barrage"], [13, "aura-of-purity", "fire-shield"], [17, "banishing-smite", "mass-cure-wounds"]];
  registry.battleSmith.grants = { 3: { weapons: ["martial"], tools: ["smiths-tools"] }, 5: { extraAttack: 2 } };
  const armorer = registry.armorer;
  armorer.alwaysPrepared = [[3, "magic-missile", "thunderwave"], [5, "mirror-image", "shatter"], [9, "hypnotic-pattern", "lightning-bolt"], [13, "fire-shield", "greater-invisibility"], [17, "passwall", "wall-of-force"]];
  armorer.grants = { 3: { armor: ["heavy"], tools: ["smiths-tools"] }, 5: { extraAttack: 2 } };
  registry.artillerist.alwaysPrepared = [[3, "shield", "thunderwave"], [5, "scorching-ray", "shatter"], [9, "fireball", "wind-wall"], [13, "ice-storm", "wall-of-fire"], [17, "cone-of-cold", "wall-of-force"]];
  registry.artillerist.grants = { 3: { tools: ["woodcarvers-tools"] } };
  const alchemist = registry.alchemist;
  alchemist.alwaysPrepared = [[3, "healing-word", "ray-of-sickness"], [5, "flaming-sphere", "melfs-acid-arrow"], [9, "gaseous-form", "mass-healing-word"], [13, "blight", "death-ward"], [17, "cloudkill", "raise-dead"]];
  alchemist.grants = {
    3: { tools: ["alchemists-supplies"] },
    9: { innateSpells: [{ id: "lesser-restoration", ability: "int", castLevel: 2, reset: "long", resource: "alchemist-restoration" }] },
    15: { resistances: ["acide", "poison"], immunities: ["empoisonné"], innateSpells: ["greater-restoration", "heal"].map((id) => ({ id, ability: "int", castLevel: id === "heal" ? 6 : 5, reset: "long", noMaterial: true, resource: `alchemist-${id}` })) },
  };
}
FEATURES.artificer = Object.values(ARTIFICER_REFERENCE_DATA).filter((ref) => ref.referenceId.startsWith("classfeature|") && ref.englishName !== "Optional Rule: Firearm Proficiency" && !["Ability Score Improvement", "Artificer Specialist Feature"].includes(ref.englishName)).map((ref) => [ref.level, ref.name, ref.description, ref.referenceId]);

// Les résultats et leurs règles restent raccordés au texte traduit de référence.
const ALCHEMIST_ELIXIRS = artificerReference("Experimental Elixir", "Alchemist").entries.find((entry) => entry.type === "table").rows.map((row) => ({ result: Number(row[0]), name: row[1].match(/\{@b ([^}]+)}/)[1], description: row[1] }));

const ARMORER_MODELS = { guardian: "Gardien", infiltrator: "Infiltrateur" };
const ARMORER_PARTS = { chest: "Torse", boots: "Bottes", helmet: "Casque", weapon: "Arme spéciale" };
/** Les armes spéciales ne possèdent ni la propriété munitions ni lancer. */
function armorerRecipePart(id) {
  const recipe = ARTIFICER_RECIPES[id];
  if (!recipe) return null;
  const items = (recipe.prerequisite || []).flatMap((entry) => entry.item || []).join(" ");
  if (/suit of armor/.test(items)) return "chest";
  if (/pair of boots/.test(items) || /^replicate:.*\|(?:boots(?: |$)|winged boots$)/.test(id)) return "boots";
  if (/helmet/.test(items) || /^replicate:.*\|helm /.test(id)) return "helmet";
  if (/simple or martial weapon/.test(items) && !/ammunition|thrown/.test(items)) return "weapon";
  return null;
}
const ARTILLERIST_MODES = { flamethrower: "Lance-flammes", ballista: "Baliste de force", protector: "Protecteur" };

/** Un lien local explicite, jamais un effet issu d'un snapshot importé. */
function artificerInfusionLink(c, item) {
  const link = c?.infusions?.find((row) => row.schemaVersion === 1 && row.id === item?.instance?.infusionId && row.itemId === item.id && row.creatorId === c.id && row.active);
  if (!link || !ARTIFICER_RECIPES[link.recipeId]) return null;
  const level = c.levels.filter((row) => row.classId === "artificer").length;
  const recipe = ARTIFICER_RECIPES[link.recipeId];
  if (level < recipe.minLevel || !(c.picks?.["artificer|recipes|recipes"] || []).includes(link.recipeId)) return null;
  return { ...link, level, recipe };
}
function artificerInfusionBonuses(c, item) {
  const link = artificerInfusionLink(c, item);
  if (!link || item.instance.attunement.required && !item.instance.attunement.active) return {};
  const name = link.recipe.englishName, enhanced = link.level >= 10 ? 2 : 1;
  if (name === "Enhanced Weapon") return { weapon: enhanced, magical: true };
  if (["Returning Weapon", "Radiant Weapon", "Repeating Shot"].includes(name)) return { weapon: 1, magical: true };
  if (name === "Enhanced Defense") return { ac: enhanced };
  if (name === "Repulsion Shield") return { ac: 1 };
  if (name === "Enhanced Arcane Focus") return { spellAttack: enhanced, slot: "focus" };
  return {};
}


