// Module : monk

function monkReference(name, subclass = null, level = null) {
  return Object.values(MONK_REFERENCE_DATA).find((entry) => entry.englishName === name && (subclass === null ? !entry.subclass : entry.subclass === subclass) && (level === null || entry.level === level));
}
const monkMartialDie = (level) => level >= 17 ? 10 : level >= 11 ? 8 : level >= 5 ? 6 : 4;
const monkElementalKiLimit = (level) => level >= 17 ? 6 : level >= 13 ? 5 : level >= 9 ? 4 : level >= 5 ? 3 : 2;
const MONK_ELEMENTS = { acid: "Acide", cold: "Froid", fire: "Feu", lightning: "Foudre", poison: "Poison" };
const MONK_DISCIPLINES = {
  elementalAttunement: ["Elemental Attunement", 3, 0],
  breathOfWinter: ["Breath of Winter", 17, 6, "cone-of-cold"],
  clenchNorthWind: ["Clench of the North Wind", 6, 3, "hold-person"],
  eternalMountain: ["Eternal Mountain Defense", 17, 5, "stoneskin", false],
  fangsFireSnake: ["Fangs of the Fire Snake", 3, 1],
  fistFourThunders: ["Fist of Four Thunders", 3, 2, "thunderwave"],
  fistUnbrokenAir: ["Unbroken Air", 3, 2],
  flamesPhoenix: ["Flames of the Phoenix", 11, 4, "fireball"],
  gongSummit: ["Gong of the Summit", 6, 3, "shatter"],
  mistStance: ["Mist Stance", 11, 4, "gaseous-form", false],
  rideWind: ["Ride the Wind", 11, 4, "fly"],
  riverHungryFlame: ["River of Hungry Flame", 17, 5, "wall-of-fire"],
  rushGaleSpirits: ["Rush of the Gale Spirits", 3, 2, "gust-of-wind", false],
  shapeFlowingRiver: ["Shape the Flowing River", 3, 1],
  sweepingCinder: ["Sweeping Cinder Strike", 3, 2, "burning-hands"],
  waterWhip: ["Water Whip", 3, 2],
  waveRollingEarth: ["Wave of Rolling Earth", 17, 6, "wall-of-stone", false],
};
function monkWeaponEligible(id, kensei = false) {
  const weapon = WEAPONS[id];
  return id !== "unarmed" && !!weapon && ["simple", "martial"].includes(weapon.group) && !weapon.special && (!weapon.heavy || kensei && id === "longbow");
}
function monkKenseiOptions(kind = "any") {
  const ref = monkReference("Path of the Kensei", "Kensei", 3);
  return Object.fromEntries(Object.entries(WEAPONS).filter(([id, weapon]) => monkWeaponEligible(id, true) && (kind === "any" || !!weapon.ranged === (kind === "ranged"))).map(([id, weapon]) => [id, [weapon.name, "Maîtrise de cette arme et utilisation avec les arts martiaux.", ref.referenceId]]));
}
const MONK_VARIANTS = Object.fromEntries([["dedicatedWeapon", "Dedicated Weapon"], ["kiFueledAttack", "Ki-Fueled Attack"], ["quickenedHealing", "Quickened Healing"], ["focusedAim", "Focused Aim"]].map(([id, name]) => {
  const ref = monkReference(name);
  return [id, { id, classId: "monk", minLevel: ref.level, replaces: [], referenceId: ref.referenceId, revision: ref.revision, name: ref.name, entries: ref.englishEntries, frenchDescription: ref.description }];
}));

function completeMonkSubclasses(registry) {
  const names = { openHand: ["Way of the Open Hand", "Open Hand"], shadow: ["Way of Shadow", "Shadow"], fourElements: ["Way of the Four Elements", "Four Elements"], longDeath: ["Way of the Long Death", "Long Death"], drunkenMaster: ["Way of the Drunken Master", "Drunken Master"], kensei: ["Way of the Kensei", "Kensei"], sunSoul: ["Way of the Sun Soul", "Sun Soul"], mercy: ["Way of Mercy", "Mercy"], astralSelf: ["Way of the Astral Self", "Astral Self"], ascendantDragon: ["Way of the Ascendant Dragon", "Ascendant Dragon"] };
  const descriptions = {
    longDeath: "PV temporaires, refus de la mort et techniques nécrotiques payées en ki.", drunkenMaster: "Représentation, matériel de brasseur et techniques liées au Déluge de coups.",
    kensei: "Types d’armes maîtrisés au choix et bonus déclaré sur un exemplaire.", sunSoul: "Traits radiants, Mains brûlantes et explosions solaires payées en ki.",
    mercy: "Intuition, Médecine, herboristerie et soins ou blessures payés en ki.", astralSelf: "Bras, visage et éveil du Moi astral ; manifestations déclarées pendant 10 minutes.",
    ascendantDragon: "Langue au choix, souffle, ailes et aura draconiques avec leurs réserves.",
  };
  for (const [id, [name, subclass]] of Object.entries(names)) {
    const ref = monkReference(name);
    registry[id] ||= { grants: {}, choices: [], resources: [], desc: descriptions[id] };
    Object.assign(registry[id], { name: ref.name, source: ref.source, referenceId: ref.referenceId, revision: ref.revision });
    registry[id].features = Object.values(MONK_REFERENCE_DATA).filter((entry) => entry.subclass === subclass && entry.englishName !== name && !["Elemental Disciplines", "Forms of Your Astral Self"].includes(entry.englishName)).map((entry) => [entry.level, entry.name, entry.description, entry.referenceId]);
  }
  registry.kensei.grants = { 3: { toolChoice: { count: 1, from: ["calligraphers-supplies", "painters-supplies"] } } };
  registry.kensei.choices = [
    { key: "kenseiMelee", title: "Arme de kensei : corps à corps", levels: { 3: 1 }, options: monkKenseiOptions("melee") },
    { key: "kenseiRanged", title: "Arme de kensei : distance", levels: { 3: 1 }, options: monkKenseiOptions("ranged") },
    { key: "kenseiWeapons", title: "Nouvelle arme de kensei", levels: { 6: 1, 11: 1, 17: 1 }, options: monkKenseiOptions() },
  ];
  registry.drunkenMaster.grants = { 3: { skills: ["performance"], tools: ["brewers-supplies"] } };
  registry.mercy.grants = { 3: { skills: ["insight", "medicine"], tools: ["herbalism-kit"] } };
  registry.ascendantDragon.grants = { 3: { languageChoice: { count: 1 } } };
  const resource = (id, name, subclass, level, max = 1, note) => {
    const ref = monkReference(name, subclass, level);
    return { id, name: ref.name, minLevel: level, max, reset: "long", note: note || ref.description, referenceId: ref.referenceId };
  };
  registry.openHand.resources[0].referenceId = monkReference("Wholeness of Body", "Open Hand", 6).referenceId;
  registry.mercy.resources = [resource("monk-ultimate-mercy", "Hand of Ultimate Mercy", "Mercy", 17, 1, "Action : 5 ki et une utilisation par repos long. Rappelle à la vie une créature morte depuis 24 heures au plus ; 4d10 + SAG PV, selon la règle complète.")];
  registry.ascendantDragon.resources = [
    resource("monk-draconic-presence", "Draconic Disciple", "Ascendant Dragon", 3, 1, "Dépense uniquement quand ta relance de Persuasion ou d’Intimidation transforme un échec en réussite."),
    resource("monk-dragon-breath", "Breath of the Dragon", "Ascendant Dragon", 3, ({ prof }) => prof, ({ level }) => `${level >= 11 ? 3 : 2}d${monkMartialDie(level)} dégâts, sauvegarde de DEX contre ton DD de ki. Quand les usages gratuits sont épuisés : 2 ki.${level >= 17 ? " Souffle augmenté : +1 ki, 4 dés d’arts martiaux." : ""}`),
    resource("monk-dragon-wings", "Wings Unfurled", "Ascendant Dragon", 6, ({ prof }) => prof, "Avec Pas du vent (1 ki) : vitesse de vol égale à ta marche jusqu’à la fin du tour. Une utilisation propre aux ailes."),
    resource("monk-dragon-aspect", "Aspect of the Wyrm", "Ascendant Dragon", 11, 1, "Action bonus, 1 minute. Une utilisation gratuite par repos long, puis 3 ki. Choisis la peur ou une résistance personnelle parmi les cinq éléments draconiques."),
  ];
  registry.ascendantDragon.resources[0].name = "Présence draconique : relance réussie";
  for (const [id, [name, minLevel, cost]] of Object.entries(MONK_DISCIPLINES)) {
    const ref = monkReference(name);
    DISCIPLINES[id] = [ref.name, ref.description, minLevel, cost ? `${cost} ki` : "Sans ki", ref.referenceId];
    CHOICE_REFERENCES.disciplines ||= {};
    CHOICE_REFERENCES.disciplines[id] = { referenceId: ref.referenceId, revision: ref.revision };
  }
  for (const spec of registry.kensei.choices) CHOICE_REFERENCES[spec.key] = Object.fromEntries(Object.entries(spec.options).map(([id, option]) => [id, { referenceId: option[2], revision: monkReference("Path of the Kensei", "Kensei", 3).revision }]));
  const classNames = ["Unarmored Defense", "Martial Arts", "Ki", "Unarmored Movement", "Monastic Tradition", "Deflect Missiles", "Slow Fall", "Extra Attack", "Stunning Strike", "Ki-Empowered Strikes", "Evasion", "Stillness of Mind", "Unarmored Movement improvement", "Purity of Body", "Tongue of the Sun and Moon", "Diamond Soul", "Timeless Body", "Empty Body", "Perfect Self"];
  FEATURES.monk = FEATURES.monk.map((feature, index) => {
    const ref = monkReference(classNames[index], null, feature[0]);
    return [feature[0], feature[1], ref.description, ref.referenceId];
  });
}


