// Module : wizard

function wizardReference(name, subclass = null, level = null) {
  return Object.values(WIZARD_REFERENCE_DATA).find((entry) => entry.englishName === name && (subclass === null ? !entry.subclass : entry.subclass === subclass) && (level === null || entry.level === level));
}

function completeWizardSubclasses(registry) {
  const definitions = { abjuration: ["Abjuration", "School of Abjuration"], conjuration: ["Conjuration", "School of Conjuration"], divination: ["Divination", "School of Divination"], enchantment: ["Enchantment", "School of Enchantment"], evocation: ["Evocation", "School of Evocation"], illusion: ["Illusion", "School of Illusion"], necromancy: ["Necromancy", "School of Necromancy"], transmutation: ["Transmutation", "School of Transmutation"], warMagic: ["War", "War Magic"], chronurgy: ["Chronurgy", "Chronurgy Magic"], graviturgy: ["Graviturgy", "Graviturgy Magic"], bladesinging: ["Bladesinging", "Bladesinging"], scribes: ["Scribes", "Order of Scribes"] };
  for (const [id, [short, name]] of Object.entries(definitions)) {
    const top = wizardReference(name), old = registry[id];
    const refs = Object.values(WIZARD_REFERENCE_DATA).filter((ref) => ref.subclass === short && ref.englishName !== name && ref.englishName !== "Bladesinger Styles");
    registry[id] = { ...old, name: top.name, source: top.source, referenceId: top.referenceId, revision: top.revision, desc: old?.desc || top.description, features: refs.map((ref) => [ref.level, ref.name, ref.description, ref.referenceId]), grants: old?.grants || {}, choices: old?.choices || [], resources: old?.resources || [] };
  }
  const resource = (id, sub, name, level, reset = "long", max = 1) => { const ref = wizardReference(name, sub, level); return { id, name: ref.name, minLevel: level, reset, max, note: ref.description, referenceId: ref.referenceId }; };
  registry.chronurgy.resources = [resource("wizard-chronal-shift", "Chronurgy", "Chronal Shift", 2, "long", 2), resource("wizard-momentary-stasis", "Chronurgy", "Momentary Stasis", 6, "long", ({ mods }) => Math.max(1, mods.int)), resource("wizard-arcane-abeyance", "Chronurgy", "Arcane Abeyance", 10, "short")];
  registry.graviturgy.resources = [resource("wizard-violent-attraction", "Graviturgy", "Violent Attraction", 10, "long", ({ mods }) => Math.max(1, mods.int)), resource("wizard-event-horizon", "Graviturgy", "Event Horizon", 14)];
  registry.bladesinging.resources = [resource("wizard-bladesong", "Bladesinging", "Bladesong", 2, "long", ({ prof }) => prof)];
  registry.transmutation.grants = { ...registry.transmutation.grants, 6: { optionChoice: { key: "transmuterStone", title: "Pierre du transmutateur : bienfait porté", count: 1, options: { none: ["Aucun, ou autre porteur", "Aucun effet personnel."], darkvision: ["Vision dans le noir", "18 m."], speed: ["Vitesse", "+3 m si tu n’es pas encombré."], con: ["Sauvegardes de Constitution", "Maîtrise."], acid: ["Résistance à l’acide", ""], cold: ["Résistance au froid", ""], fire: ["Résistance au feu", ""], lightning: ["Résistance à la foudre", ""], thunder: ["Résistance au tonnerre", ""] } } } };
  registry.illusion.grants = { ...registry.illusion.grants, 2: { ...(registry.illusion.grants[2] || {}) } };
  registry.bladesinging.grants = { 2: { armor: ["light"], weaponChoice: { count: 1, from: "wizardMelee" }, skills: ["performance"] }, 6: { extraAttack: 2 } };
  registry.scribes.resources = [resource("wizard-manifest-mind", "Scribes", "Manifest Mind", 6), { ...resource("wizard-mind-cast", "Scribes", "Manifest Mind", 6, "long", ({ prof }) => prof), name: "Lancement depuis l’esprit manifesté" }, resource("wizard-scrivener-scroll", "Scribes", "Master Scrivener", 10), resource("wizard-one-with-word", "Scribes", "One with the Word", 14)];
  registry.warMagic.resources = [resource("wizard-power-surge", "War", "Power Surge", 6, "manual", ({ mods }) => Math.max(1, mods.int))];
}

const cantripFormulas = wizardReference("Cantrip Formulas");
const WIZARD_VARIANTS = { wizardCantripFormulas: { id: "wizardCantripFormulas", classId: "wizard", minLevel: 3, replaces: [], referenceId: cantripFormulas.referenceId, revision: cantripFormulas.revision, name: cantripFormulas.name, entries: cantripFormulas.englishEntries, frenchDescription: cantripFormulas.description } };


