// Module : spell-dice

// Dés de dégâts d'un sort lancé : l'emplacement fixe les dés des sorts de niveau 1 et plus,
// le niveau du personnage ceux des sorts mineurs. Cibles, réussites et résistances restent à la table.
function spellDamageRolls(spellId, { slotLevel = 0, characterLevel = 1, modifier = 0 } = {}) {
  const data = SPELL_DICE[spellId];
  if (!data) return null;
  const tier = (table) => Object.entries(table).filter(([level]) => Number(level) <= characterLevel).at(-1)?.[1];
  const count = !data.count ? 1 : data.count.tiers ? tier(data.count.tiers) : data.count.base + Math.max(0, slotLevel - data.count.from);
  const factor = data.count?.combine ? count : 1, rolls = [];
  for (const roll of data.rolls) {
    const scaled = roll.levels ? tier(roll.levels) : `${roll.count + (roll.upcast?.levels.filter((level) => level <= slotLevel).length || 0) * (roll.upcast?.step || 0)}d${roll.sides}`;
    if (scaled === undefined) continue;
    const [dice, sides] = scaled ? scaled.split("d").map(Number) : [0, 0], bonus = ((roll.bonus || 0) + (roll.modifier ? modifier : 0)) * factor;
    const entry = dice ? { notation: `${dice * factor}d${sides}`, bonus, types: roll.types, ...(factor > 1 ? { each: { notation: `${dice}d${sides}`, bonus: bonus / factor } } : {}) } : { notation: String(Math.max(0, bonus)), bonus: 0, types: roll.types };
    // join : dégâts qui s'ajoutent au précédent (« feu et radiant ») ; sinon, une part au choix.
    if (roll.join) entry.join = true;
    if (!rolls.some((other) => other.notation === entry.notation && other.bonus === entry.bonus && other.types.join() === entry.types.join())) rolls.push(entry);
  }
  return { attack: data.attack || null, save: data.save || [], half: !!data.half, count: data.count && count > 1 ? { unit: data.count.unit, value: count, combine: !!data.count.combine } : null, rolls };
}

/** Soins d'un sort au niveau lancé : « 2d8 + 3 » pour Soins au niveau 2 avec +3 de modificateur. */
function spellHealRoll(spellId, { slotLevel = 0, modifier = 0 } = {}) {
  const heal = SPELL_DICE[spellId]?.heal;
  if (!heal) return null;
  const count = heal.count + (heal.upcast?.levels.filter((level) => level <= slotLevel).length || 0) * (heal.upcast?.step || 0);
  return { count, sides: heal.sides, bonus: (heal.bonus || 0) + (heal.modifier ? modifier : 0) };
}


