// Module : portrait-model

const PORTRAIT_MAX_BYTES = 256 * 1024;
const PORTRAIT_MAX_SIDE = 1024;

const portraitFailure = () => { throw new Error("Portrait invalide : utilise une image JPEG, PNG ou WebP statique, de 1 à 1024 pixels et de 256 Kio maximum."); };
const portraitAscii = (bytes, start, length) => String.fromCharCode(...bytes.subarray(start, start + length));
const portraitUint32 = (bytes, start) => ((bytes[start] * 0x1000000) + (bytes[start + 1] << 16) + (bytes[start + 2] << 8) + bytes[start + 3]) >>> 0;
const portraitUint32LE = (bytes, start) => ((bytes[start + 3] * 0x1000000) + (bytes[start + 2] << 16) + (bytes[start + 1] << 8) + bytes[start]) >>> 0;
function portraitPngCrc(bytes, start, end) {
  let crc = 0xffffffff;
  for (let i = start; i < end; i++) {
    crc ^= bytes[i];
    for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function portraitPngSize(bytes) {
  if (bytes.length < 57 || [137, 80, 78, 71, 13, 10, 26, 10].some((value, index) => bytes[index] !== value)) portraitFailure();
  let offset = 8, dimensions = null, data = false, ended = false;
  while (offset + 12 <= bytes.length) {
    const length = portraitUint32(bytes, offset), type = portraitAscii(bytes, offset + 4, 4), end = offset + 12 + length;
    if (end > bytes.length || !/^[A-Za-z]{4}$/.test(type) || portraitPngCrc(bytes, offset + 4, end - 4) !== portraitUint32(bytes, end - 4)) portraitFailure();
    if (offset === 8 && (type !== "IHDR" || length !== 13)) portraitFailure();
    if (type === "IHDR") {
      if (dimensions || length !== 13) portraitFailure();
      dimensions = { width: portraitUint32(bytes, offset + 8), height: portraitUint32(bytes, offset + 12) };
    }
    if (["acTL", "fcTL", "fdAT"].includes(type)) portraitFailure();
    if (type === "IDAT") data = true;
    if (type === "IEND") {
      if (length !== 0 || end !== bytes.length) portraitFailure();
      ended = true;
    }
    offset = end;
  }
  if (!dimensions || !data || !ended || offset !== bytes.length) portraitFailure();
  return dimensions;
}

function portraitJpegSize(bytes) {
  if (bytes.length < 14 || bytes[0] !== 0xff || bytes[1] !== 0xd8 || bytes.at(-2) !== 0xff || bytes.at(-1) !== 0xd9) portraitFailure();
  let offset = 2, dimensions = null, scanned = false;
  while (offset + 4 <= bytes.length) {
    if (bytes[offset++] !== 0xff) portraitFailure();
    while (bytes[offset] === 0xff) offset++;
    const marker = bytes[offset++], length = bytes[offset] * 256 + bytes[offset + 1];
    if (length < 2 || offset + length > bytes.length - 2) portraitFailure();
    if ([0xc0, 0xc1, 0xc2].includes(marker)) {
      if (dimensions || length < 8 || bytes[offset + 2] !== 8) portraitFailure();
      dimensions = { width: bytes[offset + 5] * 256 + bytes[offset + 6], height: bytes[offset + 3] * 256 + bytes[offset + 4] };
    }
    if (marker === 0xda) { scanned = true; break; }
    if ([0x00, 0x01, 0xd8, 0xd9].includes(marker) || (marker >= 0xd0 && marker <= 0xd7)) portraitFailure();
    offset += length;
  }
  if (!dimensions || !scanned) portraitFailure();
  return dimensions;
}

function portraitWebpSize(bytes) {
  if (bytes.length < 26 || portraitAscii(bytes, 0, 4) !== "RIFF" || portraitAscii(bytes, 8, 4) !== "WEBP" || portraitUint32LE(bytes, 4) !== bytes.length - 8) portraitFailure();
  let offset = 12, dimensions = null, extended = null;
  while (offset + 8 <= bytes.length) {
    const type = portraitAscii(bytes, offset, 4), length = portraitUint32LE(bytes, offset + 4), start = offset + 8, end = start + length;
    if (end > bytes.length) portraitFailure();
    if (["ANIM", "ANMF"].includes(type)) portraitFailure();
    if (type === "VP8X") {
      if (extended || offset !== 12 || length !== 10 || (bytes[start] & 2)) portraitFailure();
      extended = { width: 1 + bytes[start + 4] + (bytes[start + 5] << 8) + (bytes[start + 6] << 16), height: 1 + bytes[start + 7] + (bytes[start + 8] << 8) + (bytes[start + 9] << 16) };
    }
    if (type === "VP8 ") {
      if (dimensions || length < 10 || (bytes[start] & 1) || bytes[start + 3] !== 0x9d || bytes[start + 4] !== 0x01 || bytes[start + 5] !== 0x2a) portraitFailure();
      dimensions = { width: (bytes[start + 6] + (bytes[start + 7] << 8)) & 0x3fff, height: (bytes[start + 8] + (bytes[start + 9] << 8)) & 0x3fff };
    }
    if (type === "VP8L") {
      if (dimensions || length < 5 || bytes[start] !== 0x2f || (bytes[start + 4] >> 5) !== 0) portraitFailure();
      dimensions = { width: 1 + bytes[start + 1] + ((bytes[start + 2] & 0x3f) << 8), height: 1 + (bytes[start + 2] >> 6) + (bytes[start + 3] << 2) + ((bytes[start + 4] & 0xf) << 10) };
    }
    offset = end + (length % 2);
  }
  if (offset !== bytes.length || !dimensions || (extended && (extended.width !== dimensions.width || extended.height !== dimensions.height))) portraitFailure();
  return dimensions;
}

/** Lecture bornée de la signature et des dimensions ; aucune URL distante ni SVG. */
function portraitImageInfo(dataUrl) {
  if (typeof dataUrl !== "string" || dataUrl.length > Math.ceil(PORTRAIT_MAX_BYTES / 3) * 4 + 32) portraitFailure();
  const match = /^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/]+={0,2})$/.exec(dataUrl);
  if (!match || match[2].length % 4 !== 0) portraitFailure();
  let decoded;
  try { decoded = atob(match[2]); } catch { portraitFailure(); }
  if (!decoded.length || decoded.length > PORTRAIT_MAX_BYTES || btoa(decoded) !== match[2]) portraitFailure();
  const bytes = Uint8Array.from(decoded, (character) => character.charCodeAt(0));
  const dimensions = ({ jpeg: portraitJpegSize, png: portraitPngSize, webp: portraitWebpSize })[match[1]](bytes);
  if (![dimensions.width, dimensions.height].every((side) => Number.isInteger(side) && side >= 1 && side <= PORTRAIT_MAX_SIDE)) portraitFailure();
  return { mime: `image/${match[1]}`, bytes: bytes.length, ...dimensions };
}

function validatePortrait(value) {
  if (value == null) return null;
  if (typeof value !== "object" || Array.isArray(value) || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) portraitFailure();
  if (value.kind === "none" && Object.keys(value).length === 1) return { kind: "none" };
  if (value.kind === "preset") {
    if (Object.keys(value).some((key) => !["kind", "id"].includes(key)) || typeof value.id !== "string" || !PORTRAITS.some((portrait) => portrait.id === value.id))
      throw new Error("Portrait de la bibliothèque inconnu.");
    return { kind: "preset", id: value.id };
  }
  if (value.kind !== "custom" || Object.keys(value).some((key) => !["kind", "dataUrl", "width", "height"].includes(key))) portraitFailure();
  const info = portraitImageInfo(value.dataUrl);
  if (value.width !== info.width || value.height !== info.height) portraitFailure();
  return { kind: "custom", dataUrl: value.dataUrl, width: info.width, height: info.height };
}


// Module : portraits

function portraitFamilyOf(character) {
  const raceId = character?.raceId, inheritedId = RACES[raceId]?.portraitRaceId;
  return PORTRAIT_FAMILIES.find((family) => family.raceIds.includes(raceId)) ||
    PORTRAIT_FAMILIES.find((family) => family.raceIds.includes(inheritedId)) || PORTRAIT_FAMILIES[0];
}

function portraitEntryOf(character) {
  return PORTRAITS.find((portrait) => character?.portrait?.kind === "preset" && portrait.id === character.portrait.id) ||
    PORTRAITS.find((portrait) => portrait.family === portraitFamilyOf(character).id && portrait.sex === "female" && portrait.variant === 1);
}

function portraitUrl(character) {
  if (character?.portrait?.kind === "none") return null;
  if (character?.portrait?.kind === "custom") return character.portrait.dataUrl;
  const entry = portraitEntryOf(character);
  return globalThis.COMPANION_PORTRAIT_URLS?.[entry.id] || entry.url;
}

/** Décode localement le fichier. Le navigateur applique aussi l’orientation EXIF. */
async function loadPortraitFile(file) {
  if (!file || !file.size) throw new Error(uiText("Choisis une image non vide."));
  if (file.size > 25 * 1024 * 1024) throw new Error(uiText("Cette image dépasse 25 Mo. Choisis une version plus petite."));
  if (!/^image\/(jpeg|png|webp)$/i.test(file.type)) throw new Error(uiText("Choisis une image JPEG, PNG ou WebP. Pour une photo HEIC, exporte-la d’abord en JPEG."));
  const header = new Uint8Array(await file.slice(0, 12).arrayBuffer());
  const signature = file.type === "image/jpeg" ? [255, 216, 255].every((byte, index) => header[index] === byte) :
    file.type === "image/png" ? [137, 80, 78, 71, 13, 10, 26, 10].every((byte, index) => header[index] === byte) :
      String.fromCharCode(...header.slice(0, 4)) === "RIFF" && String.fromCharCode(...header.slice(8, 12)) === "WEBP";
  if (!signature) throw new Error(uiText("Le fichier ne correspond pas au format annoncé. Essaie une copie JPEG, PNG ou WebP."));
  const url = URL.createObjectURL(file), picture = new Image();
  try {
    picture.src = url;
    await picture.decode();
    if (!picture.naturalWidth || !picture.naturalHeight || picture.naturalWidth * picture.naturalHeight > 50000000)
      throw new Error(uiText("L’image dépasse 50 mégapixels ou ne contient pas de photo lisible."));
    return { picture, url, dispose: () => URL.revokeObjectURL(url) };
  } catch (error) {
    URL.revokeObjectURL(url);
    if (error.message === uiText("L’image dépasse 50 mégapixels ou ne contient pas de photo lisible.")) throw error;
    throw new Error(uiText("Cette image n’a pas pu être ouverte. Essaie une copie JPEG ou PNG."));
  }
}

function portraitCropRect(width, height, crop = {}) {
  const bound = (value, fallback, min, max) => Number.isFinite(Number(value)) ? Math.max(min, Math.min(max, Number(value))) : fallback;
  const size = Math.min(width, height) / bound(crop.zoom, 1, 1, 3);
  return { x: (width - size) * bound(crop.x, 0.5, 0, 1), y: (height - size) * bound(crop.y, 0.5, 0, 1), size };
}

function drawPortraitCrop(canvas, picture, crop) {
  const rect = portraitCropRect(picture.naturalWidth, picture.naturalHeight, crop), context = canvas.getContext("2d");
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.drawImage(picture, rect.x, rect.y, rect.size, rect.size, 0, 0, canvas.width, canvas.height);
}

function encodePortraitCrop(picture, crop) {
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = 512;
  drawPortraitCrop(canvas, picture, crop);
  for (const quality of [0.86, 0.76, 0.62, 0.45]) {
    const dataUrl = canvas.toDataURL("image/webp", quality);
    if ((dataUrl.split(",")[1]?.length || Infinity) * 0.75 <= PORTRAIT_MAX_BYTES) {
      return validatePortrait({ kind: "custom", dataUrl, width: 512, height: 512 });
    }
  }
  // Les navigateurs sans encodeur WebP peuvent renvoyer un PNG trop volumineux.
  const context = canvas.getContext("2d");
  context.globalCompositeOperation = "destination-over";
  context.fillStyle = "#f5f1e9";
  context.fillRect(0, 0, 512, 512);
  return validatePortrait({ kind: "custom", dataUrl: canvas.toDataURL("image/jpeg", 0.8), width: 512, height: 512 });
}


// Module : creation-identity

/** Repères descriptifs arrondis, librement modifiables, sans effet sur les règles.
 * Inspirations : tables heightAndWeight et descriptions Size de data/en/races.json
 * (PHB 2014, Volo 2016, EEPC 2015). Les révisions Multivers reprennent seulement
 * cette inspiration visuelle, pas les anciennes règles ou des limites de taille.
 * Les variantes Petite et les origines maison ont un repère générique éditorial.
 * Le portrait choisi ne détermine ni la taille ni le poids du personnage.
 */
const CREATION_IDENTITY_SUGGESTIONS = Object.freeze(Object.fromEntries(Object.entries({
  human: ["1,70 m", "80 kg", "race|phb|human"],
  humanVariant: ["1,70 m", "80 kg", "race|phb|human"],
  hillDwarf: ["1,25 m", "75 kg", "subrace|phb|hill|dwarf|phb"],
  mountainDwarf: ["1,35 m", "85 kg", "subrace|phb|mountain|dwarf|phb"],
  highElf: ["1,65 m", "60 kg", "subrace|phb|high|elf|phb"],
  woodElf: ["1,65 m", "65 kg", "subrace|phb|wood|elf|phb"],
  drow: ["1,50 m", "50 kg", "subrace|phb|drow|elf|phb"],
  lightfoot: ["0,90 m", "20 kg", "race|phb|halfling"],
  stout: ["0,90 m", "20 kg", "race|phb|halfling"],
  dragonborn: ["1,90 m", "120 kg", "race|phb|dragonborn"],
  forestGnome: ["1,00 m", "20 kg", "race|phb|gnome"],
  rockGnome: ["1,00 m", "20 kg", "race|phb|gnome"],
  halfElf: ["1,65 m", "80 kg", "race|phb|half-elf"],
  halfOrc: ["1,75 m", "110 kg", "race|phb|half-orc"],
  tiefling: ["1,65 m", "80 kg", "race|phb|tiefling"],
  goliathVgm: ["2,25 m", "155 kg", "race|vgm|goliath"],
  goliath: ["2,25 m", "155 kg", "race|vgm|goliath"],
  kenku: ["1,50 m", "50 kg", "race|vgm|kenku"],
  aasimar: ["1,70 m", "80 kg", "race|vgm|aasimar"],
  airGenasi: ["1,70 m", "80 kg", "race|eepc|genasi"],
  earthGenasi: ["1,70 m", "80 kg", "race|eepc|genasi"],
  fireGenasi: ["1,70 m", "80 kg", "race|eepc|genasi"],
  waterGenasi: ["1,70 m", "80 kg", "race|eepc|genasi"],
}).map(([raceId, [height, weight, inspirationReferenceId]]) => [raceId, Object.freeze({ height, weight, inspirationReferenceId })])));

const creationIdentityFields = ["height", "weight", "portrait"];
const creationIdentityPortraitIds = new Set(PORTRAITS.map((portrait) => portrait.id));
const creationIdentitySmall = Object.freeze({ height: "1,00 m", weight: "20 kg", inspirationReferenceId: null });
const creationIdentityMedium = Object.freeze({ height: "1,70 m", weight: "70 kg", inspirationReferenceId: null });

function creationIdentitySize(character) {
  const race = RACES[character?.raceId];
  if (character?.raceId === "custom") return character.customRace?.size === "P" ? "P" : "M";
  return race?.sizeChoice && ["P", "M"].includes(character.picks?.["race|size"]?.[0]) ? character.picks["race|size"][0] : race?.size || "M";
}

function creationIdentitySuggestion(character) {
  const raceId = character?.raceId;
  if (creationIdentitySize(character) === "P" && (!CREATION_IDENTITY_SUGGESTIONS[raceId] || RACES[raceId].sizeChoice)) return creationIdentitySmall;
  return Object.hasOwn(CREATION_IDENTITY_SUGGESTIONS, raceId) ? CREATION_IDENTITY_SUGGESTIONS[raceId] : creationIdentityMedium;
}

function creationIdentityStateValid(state) {
  return state?.version === 1 && typeof state.originKey === "string" &&
    creationIdentityFields.every((field) => typeof state.automatic?.[field] === "boolean") &&
    ["height", "weight"].every((field) => typeof state.values?.[field] === "string" && state.values[field].length < 40) &&
    (state.values.portrait === null || creationIdentityPortraitIds.has(state.values.portrait)) &&
    state.portraits && typeof state.portraits === "object" && !Array.isArray(state.portraits) &&
    Object.values(state.portraits).every((id) => creationIdentityPortraitIds.has(id));
}

function creationIdentityMatches(character, field, expected) {
  if (field !== "portrait") return (character.details?.[field] ?? "") === expected;
  return expected === null ? character.portrait == null : character.portrait?.kind === "preset" && character.portrait.id === expected;
}

/** Renvoie un nouvel état ; seul initialize:true autorise un brouillon neuf.
 * Sans métadonnées, une reprise ancienne reste intacte. Une correction de fiche
 * reste intacte même si ses métadonnées ont été conservées par un appelant.
 */
function applyCreationIdentityDefaults(wizard, { random = Math.random, initialize = false } = {}) {
  if (!wizard?.draft || wizard.original) return wizard;
  const previous = wizard.identityDefaults, valid = creationIdentityStateValid(previous);
  if (!valid && (!initialize || previous != null)) return wizard;
  const character = wizard.draft, suggestion = creationIdentitySuggestion(character);
  const raceId = character.raceId || "human", originKey = `${raceId}:${creationIdentitySize(character)}`;
  const automatic = Object.fromEntries(creationIdentityFields.map((field) => [field, valid ?
    previous.automatic[field] && creationIdentityMatches(character, field, previous.values[field]) :
    field === "portrait" ? character.portrait == null : !character.details?.[field]]));
  const portraits = { ...(valid ? previous.portraits : {}) };
  let portraitId = valid ? previous.values.portrait : null;
  if (automatic.portrait) {
    const family = portraitFamilyOf(character).id;
    const entries = PORTRAITS.filter((portrait) => portrait.family === family);
    portraitId = Object.hasOwn(portraits, raceId) && entries.some((portrait) => portrait.id === portraits[raceId]) ? portraits[raceId] : null;
    if (!portraitId) {
      const sample = Number(random());
      const index = Number.isFinite(sample) ? Math.max(0, Math.min(entries.length - 1, Math.floor(sample * entries.length))) : 0;
      portraitId = entries[index].id;
      portraits[raceId] = portraitId;
    }
  }
  const values = { height: suggestion.height, weight: suggestion.weight, portrait: portraitId };
  const identityDefaults = { version: 1, originKey, automatic, values, portraits };
  const details = { ...character.details };
  for (const field of ["height", "weight"]) if (automatic[field]) details[field] = values[field];
  const draft = { ...character, details };
  if (automatic.portrait) draft.portrait = { kind: "preset", id: portraitId };
  return { ...wizard, draft, identityDefaults };
}

/** Appeler sur une saisie ou un choix explicite, y compris un champ vidé ou
 * « sans portrait ». Une valeur identique à la suggestion devient aussi manuelle.
 */
function markCreationIdentityManual(wizard, field) {
  if (wizard?.original || !creationIdentityFields.includes(field) || !creationIdentityStateValid(wizard?.identityDefaults)) return wizard;
  return { ...wizard, identityDefaults: { ...wizard.identityDefaults, automatic: { ...wizard.identityDefaults.automatic, [field]: false } } };
}


// Module : reference-texts
const referencePointerPart = (s) => String(s).replaceAll("~", "~0").replaceAll("/", "~1");

