const referenceMechanicalTextRoots = new Set(["prerequisite", "additionalSpells", "skillProficiencies", "languageProficiencies", "toolProficiencies", "weaponProficiencies", "armorProficiencies", "savingThrowProficiencies", "resist", "immune", "conditionImmune", "vulnerable", "ability", "featProgression"]);
