// Module : dashboard-layout
/** Disposition personnelle de la fiche, indépendante des règles et du DOM. */
const DASHBOARD_ZONES = Object.freeze(["left", "center", "right"]);
const DASHBOARD_DEFAULTS = Object.freeze([
  Object.freeze(["skills", "saves", "abilities"]),
  Object.freeze(["slots", "attacks", "senses"]),
  Object.freeze(["states", "resources", "aptitudes"]),
]);

function normalizeDashboard(candidate, characterId) {
  const layout = {
    schema: "compagnon.dashboard", version: 1, characterId,
    zones: DASHBOARD_ZONES.map((id) => ({ id, components: [] })),
  };
  const known = new Set(DASHBOARD_DEFAULTS.flat());
  const seen = new Set();
  const compatible = candidate?.schema === layout.schema && candidate.version === 1 && Array.isArray(candidate.zones);
  if (compatible) {
    for (const zone of candidate.zones) {
      const target = layout.zones.find((entry) => entry.id === zone?.id);
      if (!target || !Array.isArray(zone.components)) continue;
      for (const value of zone.components) {
        const id = value === "spells" ? "slots" : value;
        if (!known.has(id) || seen.has(id)) continue;
        seen.add(id);
        target.components.push(id);
      }
    }
  }
  DASHBOARD_DEFAULTS.forEach((ids, index) => {
    for (const id of ids) if (!seen.has(id)) layout.zones[index].components.push(id);
  });
  return layout;
}

function moveDashboardComponent(candidate, componentId, zoneId, beforeId = null) {
  const layout = normalizeDashboard(candidate, candidate?.characterId);
  const target = layout.zones.find((zone) => zone.id === zoneId);
  if (!target || componentId === beforeId || !DASHBOARD_DEFAULTS.flat().includes(componentId)) return layout;
  for (const zone of layout.zones) zone.components = zone.components.filter((id) => id !== componentId);
  const index = target.components.indexOf(beforeId);
  target.components.splice(index < 0 ? target.components.length : index, 0, componentId);
  return layout;
}


