        const option = battleSmithPayments(c).find((entry) => entry.id === payment);
        if (!option) throw new Error(uiText("Choisis un emplacement disponible de niveau 1 ou supérieur."));
        if (payment === "pact") next.state.pactUsed = (next.state.pactUsed || 0) + 1;
