    if (melee && weaponDie && raceOf(c)?.id === "halfOrc") options.push({ id: "savage-attacks", label: uiText("Attaques sauvages"), damage: { notation: `1d${weaponDie}`, type }, criticalOnly: true, doubled: false, on: true });
