  for (const id of character.state?.fighter?.runesCarried || []) if (FIGHTER_RUNES[id]) add(FIGHTER_RUNES[id][2], "state.fighter.runesCarried");
  for (const id of character.picks?.["fighter|superiorTechnique|superiorManeuver"] || []) if (CHOICE_REFERENCES.superiorManeuver[id]) add(CHOICE_REFERENCES.superiorManeuver[id].referenceId, "picks.fighter|superiorTechnique|superiorManeuver");
  for (const replacement of character.replacements || []) if (["fighter", "monk"].includes(replacement.classId)) for (const id of [replacement.from, replacement.to]) if (CHOICE_REFERENCES[replacement.field || replacement.choiceKey]?.[id]) add(CHOICE_REFERENCES[replacement.field || replacement.choiceKey][id].referenceId, "replacements");
  for (const [id, [name, oath, level]] of Object.entries(PALADIN_EFFECTS)) if (id in (character.state?.paladin?.effects || {})) add(paladinReference(name, oath ? PALADIN_OATHS[oath][1] : null, level).referenceId, `state.paladin.effects.${id}`);
  for (const replacement of character.replacements || []) if (["paladin", "ranger"].includes(replacement.classId)) for (const id of [replacement.from, replacement.to]) {
    if (["paladinCantrip", "rangerCantrip"].includes(replacement.choiceKey)) alias("spell", id, `replacements.${replacement.choiceKey}`);
    else if (CHOICE_REFERENCES.style[id]) add(CHOICE_REFERENCES.style[id].referenceId, `replacements.${replacement.classId}Style`);
  }
  if (character.state?.rogue?.ghostWalk !== undefined) add(rogueReference("Ghost Walk", "Phantom", 13).referenceId, "state.rogue.ghostWalk");
  if (character.state?.rogue?.soulTrinkets !== undefined) add(rogueReference("Tokens of the Departed", "Phantom", 9).referenceId, "state.rogue.soulTrinkets");
