  for (const [key, name, subclass, level] of [["arms", "Arms of the Astral Self", "Astral Self", 3], ["visage", "Visage of the Astral Self", "Astral Self", 6], ["awakened", "Awakened Astral Self", "Astral Self", 17], ["sharpen", "Sharpen the Blade", "Kensei", 11], ["wings", "Wings Unfurled", "Ascendant Dragon", 6], ["aspect", "Aspect of the Wyrm", "Ascendant Dragon", 11], ["emptyBody", "Empty Body", null, 18]]) if (key in (character.state?.monk?.effects || {})) add(monkReference(name, subclass, level).referenceId, `state.monk.effects.${key}`);
  const customSpells = new Set((character.custom?.spells || []).map((spell) => spell.id));
  if (character.state?.bard?.spiritSession?.spellId && !customSpells.has(character.state.bard.spiritSession.spellId)) alias("spell", character.state.bard.spiritSession.spellId, "state.bard.spiritSession.spellId");
  for (const [key, name, subclass, level] of [["starMapHeld", "Star Map", "Stars", 2], ["starry", "Starry Form", "Stars", 2], ["symbiotic", "Symbiotic Entity", "Spores", 2], ["wildfire", "Summon Wildfire Spirit", "Wildfire", 2], ["companion", "Wild Companion", null, 2], ["totem", "Spirit Totem", "Shepherd", 2], ["omen", "Cosmic Omen", "Stars", 6], ["walkerSpell", "Walker in Dreams", "Dreams", 14]]) if (key in (character.state?.druid || {})) add(druidReference(name, subclass, level).referenceId, `state.druid.${key}`);
