  for (const [path, values] of Object.entries(character.picks || {})) if (/\|(?:cantripChoice|cantrips?|spells?|rituals?)$/.test(path)) for (const id of referenceArchiveArray(values)) if (!customSpells.has(id)) alias("spell", id, `picks.${path}`);
