    if (acquisition.referenceId) {
      const revisionIsVersion = acquisition.revision === sourceVersion || /^[a-f0-9]{40}$/.test(acquisition.revision || "");
      add(acquisition.referenceId, `acquisitions.${index}`, { revision: revisionIsVersion ? "" : acquisition.revision, sourceHash: acquisition.sourceHash, sourceVersion: revisionIsVersion ? acquisition.revision : sourceVersion });
    } else if (acquisition.kind === "spell" || acquisition.spellId) alias("spell", acquisition.spellId || acquisition.value, `acquisitions.${index}`);
