    context = { ...collect(base), prerequisiteLevel: level === "race" ? 1 : Number(level) };
  const rows = Object.entries(uiFeats)
    .filter(([id, feat]) => !feat.backgroundOnly || id === current)
    .map(([id, f]) => ({ id, f, ok: meetsPrereq(base, f.prereq, undefined, context) }))
    .filter(({ id, ok }) => ok.ok || id === current)
    .filter(({ f, id }) => !query || id === current || `${f.name} ${f.englishName || ""} ${f.source}`.toLocaleLowerCase("fr-FR").includes(query))
    .sort((a, b) => a.f.name.localeCompare(b.f.name, "fr"))
    .map(({ id, f, ok }) => {
      const on = current === id;
      return `<label class="option-row ${on ? "selected" : ""} ${ok.ok ? "" : "locked"}"><input type="radio" name="${esc(path)}" data-bind="${esc(path)}" value="${esc(id)}" ${on ? "checked" : ""} ${!ok.ok && !on ? "disabled" : ""}><span><strong>${esc(f.name)}</strong> ${sourcePill(f.source)}${f.prereq ? `<em class="prereq ${ok.ok ? "" : "bad"}">${ok.ok ? uiText("Prérequis : ") : uiText("Prérequis non rempli : ")}${esc(f.prereqLabel || prereqText(f.prereq))}</em>` : ""}<p>${esc(f.summary || "")}</p>${on ? libraryReferenceButton(f.referenceId || libraryRuntimeReference("feat", id)) : ""}</span></label>`;
    })
    .join("");
  const campaignsRequired = [...new Set(Object.entries(uiFeats).filter(([id, feat]) => feat.campaign && (id === current || query && `${feat.name} ${feat.englishName || ""} ${feat.source}`.toLocaleLowerCase("fr-FR").includes(query))).map(([, feat]) => feat.campaign))];
  const campaign = campaignsRequired.map((name) => backgroundCampaign(c) === name ? `<p class="help">${uiText("Campagne {p0} : historique choisi.", { p0: esc(name) })}</p>` : `<label class="check-chip"><input type="checkbox" data-array="${path.split(".")[0]}.rulesContext.campaignOptions" value="${esc(name)}" ${(c.rulesContext?.campaignOptions || []).includes(name) ? "checked" : ""}>${uiText("Campagne {p3}", { p3: esc(name) })}</label>`).join("");
  const custom = `<label class="option-row ${current === "custom" ? "selected" : ""}"><input type="radio" name="${esc(path)}" data-bind="${esc(path)}" value="custom" ${current === "custom" ? "checked" : ""}><span><strong>${uiText("Don maison ou d’un autre livre")}</strong><p>${uiText("Nom et effets libres ; les bonus chiffrés se règlent dans Maison.")}</p></span></label>`;
  return `<div class="feat-picker"><div class="search-wrap">${icon("search", 18)}<input id="feat-search-${esc(String(level))}" class="search-input" data-bind="ui.featQuery" value="${esc(ui.featQuery || "")}" placeholder="${uiText("Chercher un don…")}" aria-label="${uiText("Chercher un don")}"></div>${campaign}<div class="option-scroll tall">${rows || ("<p class=\"small muted\">" + uiText("Aucun don ne correspond.") + "</p>")}${custom}</div></div>`;
