  const changeLine = (change, describe) => `<p class="small">${change.before ? uiText("Retiré : {p0}", { p0: esc(describe(change.before)) }) : ""}${change.before && change.after ? "<br>" : ""}${change.after ? uiText("Ajouté : {p0}", { p0: esc(describe(change.after)) }) : ""}</p>`;
