        return `<button type="button" class="choice-card ${l.classId === o.classId ? "selected" : ""} ${o.ok ? "" : "locked"}" data-action="level-class" data-id="${o.classId}" ${o.ok ? "" : "disabled"} title="${esc(o.reasons.join(" ; "))}">${l.classId === o.classId ? `<span class="selected-check">${icon("check", 14)}</span>` : ""}<div class="choice-icon">${icon(uiClasses[o.classId].icon, 22)}</div><span class="choice-name">${uiClasses[o.classId].name} ${k}</span><span class="choice-meta">${o.ok ? (o.current ? uiText("Continuer") : uiText("Multiclasser")) : esc(o.reasons.join(" ; ") || uiText("Prérequis manquants"))}</span></button>`;
