  return modalShell(uiText("Infuser un objet"), `${selectField(uiText("Recette connue"), "form.recipeId", f.recipeId, { "": uiText("Choisir…"), ...options })}${recipe ? `<p>${esc(infusionPrerequisite(f.recipeId))}</p>${replica ? ("<p class=\"small\">" + uiText("Ajoute un exemplaire au sac avec sa référence.") + "</p>") : selectField(uiText("Exemplaire non magique"), "form.itemId", f.itemId, { "": uiText("Choisir…"), ...Object.fromEntries(items.map((item) => [item.id, item.name])) })}${recipe.englishName === "Resistant Armor" ? selectField(uiText("Résistance"), "form.damageType", f.damageType, { "": uiText("Choisir…"), ...INFUSION_DAMAGE_TYPES }) : ""}${recipe.englishName === "Homunculus Servant" ? ("<p class=\"small\">" + uiText("Une fiche d’homoncule sera liée à cet exemplaire. Sa disparition se déclare en terminant l’infusion.") + "</p>") : ""}${selectField(uiText("Infusion à remplacer"), "form.replaceId", f.replaceId, { "": uiText("Aucune"), ...Object.fromEntries(status.active.map((row) => [row.id, infusionGains(c, row)])) })}${replacement ? `<p class="small">${uiText("Gains perdus : {p0}", { p0: esc(infusionGains(c, replacement)) })}</p>` : ""}${status.unlinked ? checkField(uiText("Relier une infusion déjà notée"), "form.reclaimUnlinked", f.reclaimUnlinked) : ""}${checkField(uiText("Je confirme l’objet requis, sa valeur éventuelle et son caractère non magique"), "form.prerequisiteConfirmed", f.prerequisiteConfirmed)}${checkField(uiText("Je confirme la fin du repos long, ou je corrige mon suivi"), "form.confirmed", f.confirmed)}${renderReference(recipe.referenceId)}` : ""}${error ? notice(esc(error), "warning") : `<p class="small">${uiText("Après : {p0}/{p1} places ordinaires. {p2}", { p0: infusionStatus(next).occupied, p1: status.quota.infused, p2: esc(infusionGains(next, next.infusions.at(-1))) })}</p>`}`, button(uiText("Annuler"), "close-modal") + button(uiText("Voir les conséquences"), "review-infusion", next ? "" : "disabled", "primary"), true);
