    const block = !d.armorProficient || c.state.hp === 0 || (d.wildShape?.conditions || receivedConditions(c)).some((x) => ["Inconscient", "Neutralisé", "Paralysé", "Étourdi", "Pétrifié"].includes(x));
    const effect = cast.mode ? castEffectSummary(c, d, s, casting, level) : "";
