      if (before.defender?.hp !== after.defender?.hp) impactRows.push({ label: "PV du défenseur", before: before.defender?.hp ?? 0, after: after.defender?.hp ?? 0, source: "Défenseur d’acier" });
      if (f.action === "weapon" && before.weaponId !== after.weaponId) impactRows.push({ label: "Arme utilisant INT", before: battleSmithWeaponLabel(c, before.weaponId), after: battleSmithWeaponLabel(next, after.weaponId), source: "Prêt au combat" });
      if (f.action === "correct") for (const [key, label] of [["appearance", "Apparence"], ["repairsUsed", "Réparations utilisées"]]) if (before.defender[key] !== after.defender[key]) impactRows.push({ label, before: before.defender[key], after: after.defender[key], source: "Défenseur d’acier" });
      if (f.action === "create" && before.defender) impactRows.push({ label: "Ancien défenseur", before: before.defender.name, after: "Remplacé, périt", source: "Défenseur d’acier" });
